+package ai.unifiedprocess.petclinic.vet.ui;
+
+import ai.unifiedprocess.petclinic.PetClinicTestBase;
+import ai.unifiedprocess.petclinic.UseCase;
+import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
+import com.vaadin.flow.component.Component;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.sidenav.SideNav;
+import org.jooq.DSLContext;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VETS;
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VET_SPECIALTIES;
+import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+
+/**
+ * UC-002: View Veterinarians.
+ */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    private static final int FIRST_NAME = 0;
+    private static final int LAST_NAME = 1;
+    private static final int SPECIALTIES = 2;
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Autowired
+    private VetRepository vetRepository;
+
+    @Test
+    @UseCase(id = "UC-002")
+    void veterinariansLinkInNavigationOpensTheVetsGrid() {
+        navigate("", Component.class);
+
+        SideNav menu = assertDoesNotThrow(() -> find(SideNav.class).single(), "Expected the main menu");
+        test(menu).clickItem("Veterinarians");
+
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+        assertDoesNotThrow(this::vetsGrid, "Expected the veterinarians grid after following the link");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-003")
+    void gridListsEveryVetWithSpecialtiesWithoutAuthentication() {
+        // No authentication is performed, covering BR-003 (Anonymous Access).
+        assertDoesNotThrow(() -> navigate(VetsView.class),
+                "Expected /vets to resolve to VetsView without authentication");
+
+        var grid = test(vetsGrid());
+        assertEquals(6, grid.size(), "Expected all six seeded veterinarians");
+        assertEquals("First Name", grid.getHeaderCell(FIRST_NAME));
+        assertEquals("Last Name", grid.getHeaderCell(LAST_NAME));
+        assertEquals("Specialties", grid.getHeaderCell(SPECIALTIES));
+
+        int helen = rowOf("Helen", "Leary");
+        assertEquals("radiology", grid.getCellText(helen, SPECIALTIES));
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void vetWithoutSpecialtiesShowsNone() {
+        navigate(VetsView.class);
+
+        assertEquals("none", test(vetsGrid()).getCellText(rowOf("James", "Carter"), SPECIALTIES));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void specialtiesAreListedAlphabetically() {
+        navigate(VetsView.class);
+
+        // Linda Douglas holds surgery (id 2) and dentistry (id 3): alphabetical order reverses insertion order.
+        assertEquals("dentistry, surgery",
+                test(vetsGrid()).getCellText(rowOf("Linda", "Douglas"), SPECIALTIES));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void gridLoadsVetsLazilyPageByPage() {
+        navigate(VetsView.class);
+
+        assertFalse(vetsGrid().getDataProvider().isInMemory(),
+                "Expected a callback data provider that fetches rows from the backend as the user scrolls");
+        assertEquals(2, vetRepository.findPage(0, 2).count(),
+                "Expected a page to hold only the requested number of rows");
+        assertEquals(6, vetRepository.findPage(0, 50).count() + vetRepository.findPage(50, 50).count(),
+                "Expected consecutive pages to cover every vet exactly once");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void emptyGridWhenNoVetsAreRecorded() {
+        // Rolled back by the test transaction.
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+
+        navigate(VetsView.class);
+
+        assertEquals(0, test(vetsGrid()).size(), "Expected the grid to render with no rows");
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Object> vetsGrid() {
+        return assertDoesNotThrow(() -> find(Grid.class).single(), "Expected exactly one veterinarians grid");
+    }
+
+    private int rowOf(String firstName, String lastName) {
+        var grid = test(vetsGrid());
+        for (int row = 0; row < grid.size(); row++) {
+            if (firstName.equals(grid.getCellText(row, FIRST_NAME))
+                    && lastName.equals(grid.getCellText(row, LAST_NAME))) {
+                return row;
+            }
+        }
+        throw new AssertionError("No row for " + firstName + " " + lastName);
+    }
+}
